fn v2_error_status(code: v2::DdbErrorCode) -> StatusCode {
    match code {
        v2::DdbErrorCode::Unspecified => {
            StatusCode::from_u16(500).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::InvalidArgument => {
            StatusCode::from_u16(400).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::NotFound => StatusCode::from_u16(404).expect("validated v2 HTTP status"),
        v2::DdbErrorCode::Conflict => StatusCode::from_u16(409).expect("validated v2 HTTP status"),
        v2::DdbErrorCode::FailedPrecondition => {
            StatusCode::from_u16(412).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::Unsupported => {
            StatusCode::from_u16(501).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::NotReady => StatusCode::from_u16(503).expect("validated v2 HTTP status"),
        v2::DdbErrorCode::Unauthenticated => {
            StatusCode::from_u16(401).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::PermissionDenied => {
            StatusCode::from_u16(403).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::ResourceExhausted => {
            StatusCode::from_u16(429).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::DeadlineExceeded => {
            StatusCode::from_u16(504).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::Cancelled => StatusCode::from_u16(499).expect("validated v2 HTTP status"),
        v2::DdbErrorCode::NotCancellable => {
            StatusCode::from_u16(409).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::ReplayGap => StatusCode::from_u16(410).expect("validated v2 HTTP status"),
        v2::DdbErrorCode::BackendFailed => {
            StatusCode::from_u16(502).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::PartialFailure => {
            StatusCode::from_u16(502).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::Unavailable => {
            StatusCode::from_u16(503).expect("validated v2 HTTP status")
        }
        v2::DdbErrorCode::Internal => StatusCode::from_u16(500).expect("validated v2 HTTP status"),
        v2::DdbErrorCode::Expired => StatusCode::from_u16(410).expect("validated v2 HTTP status"),
    }
}

